var setup=UnityEditor.SceneManagement.EditorSceneManager.GetSceneManagerSetup();var lines=new System.Collections.Generic.List<string>();try{foreach(var entry in UnityEditor.EditorBuildSettings.scenes.Where(e=>e.enabled&&!e.path.Contains("MainMenu"))){var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene(entry.path);int count=0,miss=0,maps=0;foreach(var map in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Tilemaps.Tilemap>())){var col=(UnityEngine.Collider2D)map.GetComponent<UnityEngine.CompositeCollider2D>()??map.GetComponent<UnityEngine.Tilemaps.TilemapCollider2D>();if(col==null)continue;maps++;var tc=map.GetComponent<UnityEngine.Tilemaps.TilemapCollider2D>();tc.ProcessTilemapChanges();UnityEngine.Physics2D.SyncTransforms();foreach(var c in map.cellBounds.allPositionsWithin)if(map.HasTile(c)&&map.GetColliderType(c)!=UnityEngine.Tilemaps.Tile.ColliderType.None){count++;if(!col.OverlapPoint(map.GetCellCenterWorld(c)))miss++;}}lines.Add(scene.name+": maps="+maps+" solidCells="+count+" missing="+miss);if(miss>0)throw new System.Exception("Reload coverage failed "+scene.name);}
UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Tutorial.unity");var source=UnityEngine.Object.FindObjectOfType<UnityEngine.Tilemaps.Tilemap>();
var test=UnityEngine.SceneManagement.SceneManager.CreateScene("IsolatedTilemapPhysics",new UnityEngine.SceneManagement.CreateSceneParameters(UnityEngine.SceneManagement.LocalPhysicsMode.Physics2D));
try{var grid=new UnityEngine.GameObject("TestGrid");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(grid,test);grid.AddComponent<UnityEngine.Grid>().cellSize=new UnityEngine.Vector3(.8f,.8f,1);var clone=UnityEngine.Object.Instantiate(source.gameObject,source.transform.position,source.transform.rotation);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(clone,test);clone.transform.SetParent(grid.transform,true);var map=clone.GetComponent<UnityEngine.Tilemaps.Tilemap>();var tc=clone.GetComponent<UnityEngine.Tilemaps.TilemapCollider2D>();var composite=clone.GetComponent<UnityEngine.CompositeCollider2D>();tc.ProcessTilemapChanges();if(composite!=null)composite.GenerateGeometry();UnityEngine.Physics2D.SyncTransforms();
var body=new UnityEngine.GameObject("PhysicsProbe");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(body,test);body.transform.position=new UnityEngine.Vector3(0,-.8f,0);var hit=body.AddComponent<UnityEngine.CircleCollider2D>();hit.radius=.15f;var rb=body.AddComponent<UnityEngine.Rigidbody2D>();rb.gravityScale=1;var physics=test.GetPhysicsScene2D();for(int i=0;i<120;i++)physics.Simulate(.02f);if(body.transform.position.y < -2.05f||body.transform.position.y > -1.7f)throw new System.Exception("Drop test failed "+body.transform.position);lines.Add("Isolated Physics2D: body landed at "+body.transform.position.ToString("F4"));
var cell=new UnityEngine.Vector3Int(100,100,0);var tile=map.GetTilesBlock(map.cellBounds).First(t=>t!=null);map.SetTile(cell,tile);map.SetTransformMatrix(cell,UnityEngine.Matrix4x4.identity);tc.ProcessTilemapChanges();if(composite!=null)composite.GenerateGeometry();UnityEngine.Physics2D.SyncTransforms();var collider=(UnityEngine.Collider2D)composite??tc;if(!collider.OverlapPoint(map.GetCellCenterWorld(cell)))throw new System.Exception("Paint did not add collision");map.SetTile(cell,null);tc.ProcessTilemapChanges();if(composite!=null)composite.GenerateGeometry();UnityEngine.Physics2D.SyncTransforms();if(collider.OverlapPoint(map.GetCellCenterWorld(cell)))throw new System.Exception("Erase did not remove collision");lines.Add("Isolated clone paint/erase collision: PASS");
}finally{UnityEditor.SceneManagement.EditorSceneManager.CloseScene(test,true);}
}finally{UnityEditor.SceneManagement.EditorSceneManager.RestoreSceneManagerSetup(setup);System.IO.File.WriteAllLines("scripts/tilemap-collision-20261110/verification.txt",lines);}return string.Join("\n",lines);
